"use client";
import { useCallback, useMemo } from "react";
import { useAgent, useAgents, useSkills } from "@polpo-ai/react";
const COMMAND_CATEGORY = "Commands";
const SKILL_CATEGORY = "Skills";
function capitalise(s) {
  return s.length ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}
function usePolpoChatSlashItems(opts = {}) {
  const {
    agent: agentName,
    skillsScope = "project",
    commands = [],
    onCommand,
    autoAssignSkillToAgent = true,
    trigger = "/"
  } = opts;
  const polpoSkills = useSkills();
  const { agent, refetch: refetchAgent } = useAgent(agentName);
  const { updateAgent } = useAgents();
  const items = useMemo(() => {
    const cmdItems = commands.map((c) => ({
      ...c,
      category: c.category ?? COMMAND_CATEGORY
    }));
    const assigned = Array.isArray(agent?.skills) ? agent.skills : [];
    const sourceSkills = skillsScope === "assigned" && agentName ? (polpoSkills.skills ?? []).filter((s) => assigned.includes(s.name)) : polpoSkills.skills ?? [];
    const skillItems = sourceSkills.map((s) => ({
      id: `skill:${s.name}`,
      label: s.name,
      description: s.description,
      // The skill's macro-category becomes the group header in the
      // grouped variant. Falls back to the generic "Skills" bucket so
      // skills without a category still cluster together.
      category: s.category ? capitalise(s.category) : SKILL_CATEGORY,
      keywords: s.tags,
      // The mini-pill on the right shows the skill's source (project,
      // global, polpo, …) so the user can tell where it came from.
      shortcut: s.source !== "project" ? s.source : void 0
    }));
    return [...cmdItems, ...skillItems];
  }, [commands, polpoSkills.skills, skillsScope, agentName, agent?.skills]);
  const triggers = useMemo(
    () => ({
      [trigger]: {
        items,
        variant: "grouped",
        defaultCategory: SKILL_CATEGORY
      }
    }),
    [items, trigger]
  );
  const onSelect = useCallback(
    async (item) => {
      if (item.id.startsWith("skill:")) {
        const skillName = item.id.slice("skill:".length);
        if (autoAssignSkillToAgent && agentName) {
          const current = Array.isArray(agent?.skills) ? agent.skills : [];
          if (!current.includes(skillName)) {
            const next = [...current, skillName];
            try {
              await updateAgent(agentName, { skills: next });
              await refetchAgent();
              await polpoSkills.refetch();
            } catch {
              await refetchAgent();
              await polpoSkills.refetch();
            }
          }
        }
        return;
      }
      const matched = commands.find((c) => c.id === item.id);
      if (matched) onCommand?.(matched);
    },
    [
      agent,
      agentName,
      autoAssignSkillToAgent,
      commands,
      onCommand,
      polpoSkills,
      refetchAgent,
      updateAgent
    ]
  );
  return {
    triggers,
    onSelect,
    items,
    isLoading: polpoSkills.isLoading
  };
}
export {
  usePolpoChatSlashItems
};
